const alerts = $input.first().json;
if (!Array.isArray(alerts) || alerts.length === 0) {
  return [{ json: { skip: true } }];
}

// Group alerts by source IP
const grouped = {};
for (const alert of alerts) {
  const ip = alert.source_ip || 'unknown';
  if (!grouped[ip]) grouped[ip] = [];
  grouped[ip].push(alert);
}

const dnaProfiles = [];

for (const [ip, ipAlerts] of Object.entries(grouped)) {
  if (ipAlerts.length < 2) continue;

  // Calculate Threat DNA scores per category
  const categories = {
    recon: ['reconnaissance', 'port_scan', 'host_sweep', 'brute_force'],
    c2: ['c2_beaconing', 'abnormal_outbound', 'suspicious_port'],
    dns_abuse: ['dga', 'dns_tunneling', 'dns_flood'],
    encrypted: ['ja3_anomaly', 'tls_anomaly', 'encrypted_malware'],
    exfiltration: ['data_exfiltration', 'large_transfer', 'asymmetric_traffic']
  };

  const scores = {};
  for (const [category, types] of Object.entries(categories)) {
    const matching = ipAlerts.filter(a => types.some(t => (a.alert_type || '').includes(t) || (a.category || '').includes(t)));
    const maxConfidence = matching.length > 0 ? Math.max(...matching.map(a => a.confidence || 50)) : 0;
    const frequency = Math.min(100, matching.length * 15);
    scores[category] = Math.round((maxConfidence * 0.6 + frequency * 0.4));
  }

  dnaProfiles.push({
    incident_id: `DNA-${ip.replace(/\./g, '-')}-${Date.now()}`,
    source_ip: ip,
    alert_count: ipAlerts.length,
    recon_score: scores.recon,
    c2_score: scores.c2,
    dns_abuse_score: scores.dns_abuse,
    encrypted_traffic_score: scores.encrypted,
    exfiltration_score: scores.exfiltration,
    overall_threat_level: Object.values(scores).reduce((a, b) => a + b, 0) / 5,
    generated_at: new Date().toISOString()
  });
}

if (dnaProfiles.length === 0) {
  return [{ json: { skip: true } }];
}

return dnaProfiles.map(d => ({ json: d }));
